def most_common_n_chars(s, n):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ordered[:n]

def dict_average_values(list_of_dicts):
    sums = {}
    counts = {}
    for d in list_of_dicts:
        for k, v in d.items():
            sums[k] = sums.get(k, 0) + v
            counts[k] = counts.get(k, 0) + 1
    return {k: sums[k] / counts[k] for k in sums}

def count_letters_ignore_case(s):
    d = {}
    for ch in s.lower():
        if ch.isalpha():
            d[ch] = d.get(ch, 0) + 1
    return d

def group_by_digit_count(nums):
    d = {}
    for x in nums:
        dc = len(str(abs(x)))
        d.setdefault(dc, []).append(x)
    return {k: sorted(v) for k, v in d.items()}

def tally_votes(votes):
    d = {}
    for v in votes:
        d[v] = d.get(v, 0) + 1
    return d

def election_winner(votes):
    counts = {}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    cands = [k for k, c in counts.items() if c == best]
    return min(cands)

def count_bigrams(text):
    words = text.split()
    d = {}
    for i in range(len(words) - 1):
        key = words[i] + " " + words[i + 1]
        d[key] = d.get(key, 0) + 1
    return d

def normalize_to_percentage(counts):
    total = sum(counts.values())
    if total == 0:
        return {k: 0 for k in counts}
    return {k: round(100 * v / total, 2) for k, v in counts.items()}

def words_appearing_once(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return sorted(w for w, c in counts.items() if c == 1)

def words_appearing_at_least(text, k):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return sorted(w for w, c in counts.items() if c >= k)

def most_common_first_occurrence(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    best = max(counts.values())
    for x in items:
        if counts[x] == best:
            return x

def count_words_case_insensitive(text):
    d = {}
    for w in text.split():
        lw = w.lower()
        d[lw] = d.get(lw, 0) + 1
    return d

def dict_merge_multiple(dicts):
    res = {}
    for d in dicts:
        for k, v in d.items():
            res[k] = res.get(k, 0) + v
    return res

def distinct_items_per_group(pairs):
    groups = {}
    for g, item in pairs:
        groups.setdefault(g, set()).add(item)
    return {g: len(s) for g, s in groups.items()}

def nested_group_counts(pairs):
    res = {}
    for g, item in pairs:
        res.setdefault(g, {})
        res[g][item] = res[g].get(item, 0) + 1
    return res

def lookup_chain(d, keys):
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return None
    return cur

def count_leaf_values(nested):
    total = 0
    for v in nested.values():
        if isinstance(v, dict):
            total += count_leaf_values(v)
        else:
            total += 1
    return total
